use std::collections::HashMap;
use std::hash::Hash;

#[derive(Debug, Clone)]
pub struct HopscotchMap<K, V> {
    entries: HashMap<K, V>,
}

impl<K, V> Default for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            entries: HashMap::new(),
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> Option<V> {
        self.entries.insert(entry.0, entry.1)
    }
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: Default,
{
    pub fn get_or_insert_default_mut(&mut self, key: K) -> &mut V {
        self.entries.entry(key).or_default()
    }
}

impl<K, V> PartialEq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: PartialEq,
{
    fn eq(&self, other: &Self) -> bool {
        self.entries == other.entries
    }
}

impl<K, V> Eq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: Eq,
{
}

