use crate::cli::parse_count;
use crate::hopscotch_map::HopscotchMap;

fn cpp_bool(value: bool) -> u8 {
    if value { 1 } else { 0 }
}

pub fn run<I>(args: I) -> String
where
    I: IntoIterator<Item = String>,
{
    let args: Vec<String> = args.into_iter().collect();
    let count = parse_count(&args);

    let mut map1 = HopscotchMap::<i32, i32>::new();
    let mut map2 = HopscotchMap::<i32, i32>::new();

    let mut i = 0_i32;
    while i < count {
        let value = i.wrapping_mul(11);
        map1.insert((i, value));
        map2.insert((i, value));
        i += 1;
    }

    let first = cpp_bool(map1 == map2);
    *map2.get_or_insert_default_mut(0) = 999;
    let second = cpp_bool(map1 == map2);

    format!("{first} {second}\n")
}

