pub fn parse_count(args: &[String]) -> i32 {
    let mut count = 14_i32;

    if args.len() > 1 && args[1] == "--a" {
        count = parse_cpp_i32(&args[2]);
    }

    count
}

fn parse_cpp_i32(input: &str) -> i32 {
    let trimmed = input.trim_start();
    let bytes = trimmed.as_bytes();

    let mut index = 0_usize;
    let mut sign = 1_i64;

    if let Some(&first) = bytes.first() {
        if first == b'+' {
            index = 1;
        } else if first == b'-' {
            index = 1;
            sign = -1;
        }
    }

    let digits_start = index;
    while let Some(&byte) = bytes.get(index) {
        if byte.is_ascii_digit() {
            index += 1;
        } else {
            break;
        }
    }

    if index == digits_start {
        panic!("invalid stoi argument");
    }

    let mut value = 0_i64;
    for &byte in &bytes[digits_start..index] {
        value = value
            .checked_mul(10)
            .and_then(|current| current.checked_add(i64::from(byte - b'0')))
            .unwrap();
    }

    value *= sign;
    i32::try_from(value).unwrap()
}
